#!/bin/bash
python3 - <<'ATPY'

import json, os, sys, time, uuid, shutil, subprocess, urllib.request, urllib.parse

WORK_DIR = os.environ.get("AT_WORK_DIR") or "/tmp"
ASSETS_DIR = os.environ.get("AT_ASSETS_DIR") or os.path.join(WORK_DIR, "assets")
AVATAR_DIR = os.path.join(ASSETS_DIR, "avatars")
VOICE_DIR = os.path.join(ASSETS_DIR, "voices")
IMG_EXT = (".png", ".jpg", ".jpeg", ".webp")
MAX_DOWNLOAD = 2 * 1024 * 1024 * 1024

def die(msg, **extra):
    out = {"error": msg}
    out.update(extra)
    print(json.dumps(out)); sys.exit(0)

def uid():
    return uuid.uuid4().hex[:10]

def now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

def arg(name, default=""):
    return os.environ.get("ARG_" + name, "") or default

def slugify(name):
    return "-".join("".join(c if c.isalnum() else " " for c in name.strip().lower()).split())

def slug_candidates(ref):
    ref = (ref or "").strip()
    out = []
    for s in (slugify(ref), ref.lower().replace(" ", "-")):
        if s and s not in out:
            out.append(s)
    return out

def write_json_atomic(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp-" + uid()
    with open(tmp, "w") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
    os.replace(tmp, path)

def fetch(source, prefix="media"):
    """Local path or http(s) URL -> existing local file path."""
    if not source:
        die("a file path or URL is required")
    if source.startswith(("http://", "https://")):
        path = urllib.parse.urlparse(source).path
        ext = os.path.splitext(path)[1][:8] or ".bin"
        os.makedirs(WORK_DIR, exist_ok=True)
        out = os.path.join(WORK_DIR, "%s-%s%s" % (prefix, uid(), ext))
        req = urllib.request.Request(source, headers={"User-Agent": "at-studio-library"})
        size = 0
        try:
            with urllib.request.urlopen(req, timeout=600) as r, open(out, "wb") as f:
                while True:
                    chunk = r.read(1 << 20)
                    if not chunk:
                        break
                    size += len(chunk)
                    if size > MAX_DOWNLOAD:
                        die("download exceeds 2 GiB: " + source)
                    f.write(chunk)
        except Exception as e:
            die("download failed: %s" % e, url=source)
        if size == 0:
            die("download was empty: " + source)
        return out
    p = os.path.abspath(os.path.expanduser(source))
    if not os.path.isfile(p):
        die("file not found: " + p)
    return p

def manifest_path(slug):
    return os.path.join(AVATAR_DIR, slug + ".json")

def find_character(ref):
    """Library character -> (slug, manifest) or None."""
    for slug in slug_candidates(ref):
        p = manifest_path(slug)
        if os.path.isfile(p):
            try:
                return slug, json.load(open(p))
            except ValueError as e:
                die("corrupt manifest for %r: %s" % (ref, e))
        for ext in IMG_EXT:
            img = os.path.join(AVATAR_DIR, slug + ext)
            if os.path.isfile(img):
                return slug, {"name": ref, "slug": slug, "file": img}
    return None

def known_characters():
    if not os.path.isdir(AVATAR_DIR):
        return []
    return sorted(os.path.splitext(f)[0] for f in os.listdir(AVATAR_DIR) if f.endswith(".json"))

def load_character(ref):
    found = find_character(ref)
    if not found:
        die("character not found in library: %r" % ref, available=known_characters())
    return found

def asset_path(rel):
    if not rel:
        return ""
    return rel if os.path.isabs(rel) else os.path.join(AVATAR_DIR, rel)

def reference_files(manifest):
    files = []
    for r in manifest.get("reference_images") or []:
        p = asset_path(r)
        if os.path.isfile(p) and p not in files:
            files.append(p)
    portrait = manifest.get("file")
    if portrait and os.path.isfile(portrait) and portrait not in files:
        files.insert(0, portrait)
    return files

def describe(manifest):
    out = dict(manifest)
    out["reference_files"] = reference_files(manifest)
    return out

def image_ext(path):
    ext = os.path.splitext(path)[1].lower()
    return ext if ext in IMG_EXT else ".png"

p = fetch(arg("VIDEO"), "clip")
out = arg("OUTPUT") or os.path.join(WORK_DIR, "lastframe-%s.png" % uid())
if not os.path.isabs(out):
    out = os.path.join(WORK_DIR, out)
os.makedirs(os.path.dirname(out), exist_ok=True)
probe = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration",
                        "-of", "default=noprint_wrappers=1:nokey=1", p], capture_output=True, text=True)
try:
    dur = float(probe.stdout.strip())
except ValueError:
    die("ffprobe could not read duration", stderr=probe.stderr[-500:])
r = subprocess.run(["ffmpeg", "-y", "-ss", "%.3f" % max(0.0, dur - 0.1), "-i", p,
                    "-frames:v", "1", "-q:v", "2", out], capture_output=True, text=True)
if r.returncode != 0 or not os.path.isfile(out) or os.path.getsize(out) == 0:
    r = subprocess.run(["ffmpeg", "-y", "-sseof", "-0.5", "-i", p,
                        "-frames:v", "1", "-q:v", "2", out], capture_output=True, text=True)
if r.returncode != 0 or not os.path.isfile(out) or os.path.getsize(out) == 0:
    die("ffmpeg failed to extract the last frame", stderr=(r.stderr or "")[-500:])
print(json.dumps({"image_file": out, "video": p, "video_duration_s": round(dur, 3)}))

ATPY
